?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title><?=e($p['name'])?></title><link rel="stylesheet" href="assets/style.css"></head><body><header class="site-header"><a class="back-mark" href="index.php">←</a><a class="wordmark" href="index.php"><?=e(setting('store_name','ATELIER'))?></a><nav><a href="cart.php">BAG <span class="bag-count"><?=cart_count()?></span></a></nav></header><main class="detail-layout"><div class="detail-image"><?php if($p['image']):?><img src="<?=e($p['image'])?>" alt="<?=e($p['name'])?>"><?php else:?><div class="image-placeholder">IMAGE COMING SOON</div><?php endif;?></div><section class="detail-info"><p class="eyebrow"><?=e(strtoupper($p['category']))?></p><h1><?=e($p['name'])?></h1><div class="detail-price"><?php if($p['sale_price']):?><del><?=rupiah($p['price'])?></del><?php endif;?><?=rupiah($p['sale_price']?:$p['price'])?></div><p class="description"><?=nl2br(e($p['description']))?></p><form method="post" action="cart.php"><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?=$p['id']?>"><label class="field-label">SELECT SIZE</label><div class="size-options"><?php if($sizes):foreach($sizes as $sz):?><label><input type="radio" name="size" value="<?=e($sz['size_name'])?>" required <?=$sz['stock']<1?'disabled':''?>><span><?=$sz['size_name']?></span></label><?php endforeach;else:?><label><input type="radio" name="size" value="One Size" checked><span>ONE SIZE</span></label><?php endif;?></div><p class="muted small">Stok tersedia: <?=$p['stock']?></p><button class="btn dark full">ADD TO BAG</button></form><div class="detail-note"><p>DETAILS</p><span>Carefully selected materials · Designed for everyday wear</span></div></section></main><footer class="site-footer"><a href="index.php">← BACK TO COLLECTION</a></footer></body></html>
